  return msg;
}
var v = Number(msg.payload && msg.payload.suhu_max);
if (isNaN(v)) {
  msg.statusCode = 400;
  msg.payload = {status:'error', message:'suhu_max harus angka'};
  return msg;
}
flow.set('threshold', v);
msg.statusCode = 200;
msg.payload = {status:'success', message:'Batas suhu diset', threshold:v};
return msg;

